// This is your JSON data, stored as a JavaScript array


// Access the string containing the values
//const outputString = jsonData[0].output;
const outputString = $input.first().json.output

// Use a regular expression to find the values
const drDescMatch = outputString.match(/\*\*`dr_desc`\*\*: `\"(.*?)\"`/);
const drValueMatch = outputString.match(/\*\*`dr_value`\*\*: `(.*?)`/);
const statusMatch = outputString.match(/\*\*`status`\*\*: `\"(.*?)\"`/);
const transDateMatch = outputString.match(/\*\*`trans_date`\*\*: `\"(.*?)\"`/);

// Extract the captured group (the value) from each match
const dr_desc = drDescMatch ? drDescMatch[1] : null;
const dr_value = drValueMatch ? parseFloat(drValueMatch[1]) : null; // Use parseFloat to convert the string to a number
const status = statusMatch ? statusMatch[1] : null;
const trans_date = transDateMatch ? transDateMatch[1] : null;


const crDescMatch = outputString.match(/\*\*`cr_desc`\*\*: `\"(.*?)\"`/);
const crValueMatch = outputString.match(/\*\*`cr_value`\*\*: `(.*?)`/);
